def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N <= 0 or not grid_values:
        return 0

    # Create a list to store the sum of values for each row
    row_sums = [0] * N

    for x, y, val in grid_values[:-1]:  # Exclude the terminating zero
        row_sums[x] += val  # Update the sum of values for the current row

    # Create a list to store the DP table for the paths
    dp = [[0] * N for _ in range(N)]

    # Fill the DP table for the paths
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j] = grid_values[0][2]  # Starting value
            elif i == 0:
                dp[i][j] = row_sums[j] + dp[0][j - 1]  # Path from top to down
            elif j == 0:
                dp[i][j] = row_sums[i] + dp[i - 1][0]  # Path from left to right
            else:
                dp[i][j] = grid_values[i][2] + max(dp[i - 1][j], dp[i][j - 1])

    # The maximum sum will be the maximum sum of two paths from the bot-left to top-right
    return max(dp[N - 1][N - 1], dp[N - 1][N - 2])
