def cantor_numbering(N: int) -> str:
    if not isinstance(N, int):
        raise TypeError("The input must be an integer.")
    if N <= 0:
        raise ValueError("The input cannot be negative or zero.")

    def get_numerator_and_denominator(n):
        if n == 1:
            return 1, 1
        elif n % 2 == 0:
            numerator, denominator = get_numerator_and_denominator(n // 2)
            return numerator - denominator, denominator
        else:
            numerator, denominator = get_numerator_and_denominator((n + 1) // 2)
            return numerator, denominator + 1

    numerator, denominator = get_numerator_and_denominator(N)
    return str(numerator) + '/' + str(denominator)
