        total_product = 1
        for i in range(max_idx, min_idx + 1):
            total_product *= int(num_str[i])
        result = max(result, total_product)

        # Insert multiplication sign if the value before max_idx is smaller
        if max_idx > 0:
            value_before = int(num_str[max_idx - 1])
