    def insert_multiplications(index):
        substrs = []
        for i in range(K + 1):
            substrs.append(num_str[:index] + '*' * i + num_str[index:])
        return substrs

    def calculate_products(substrings):
        max_product = 1
        for substring in substrings:
            product = 1
            for char in substring:
                if char.isdigit():
                    product *= int(char)
            max_product = max(max_product, product)
        return max_product

    if N < 2 * K + 1:
        return -1

    max_product = -1
    for i in range(N - K + 1):
        substrings = insert_multiplications(i)
        product = calculate_products(substrings)
        max_product = max(max_product, product)

    return max_product
