def verify_isbn(isbn: str) -> str:
    # Regular expression to validate the ISBN format
    import re
    if not re.match(r'^\d{3}-\d{2}-\d{5}-\d{1}$|^X$', isbn):
        return 'Invalid format'

    # Remove the hyphen if it exists
    isbn = isbn.replace('-', '')

    # Calculate the checksum using the standard ISBN-13 algorithm
    def calculate_checksum(s):
        sum = 0
        for i, digit in enumerate(s):
            if i % 2 == 0:
                sum += int(digit) * 1
            else:
                sum += int(digit) * 3
        return sum % 10

    # Calculate the expected checksum
    expected_checksum = calculate_checksum(isbn[:-1])

    if expected_checksum != int(isbn[-1]):
        # If the actual checksum is incorrect, correct the ISBN by updating the last digit
        for digit in range(0, 10):
            corrected_isbn = isbn[:-1] + str(digit)
            if calculate_checksum(corrected_isbn[:-1]) == int(corrected_isbn[-1]):
                return corrected_isbn

    return 'Right'
