    for i in range(n):
        dp[i][0] = 1

    # Fill DP table based on transitions
    for i in range(1, n):
        for j in range(1, m+1):
            dp[i][j] = (dp[(i-1) % n][j-1] + dp[(i+1) % n][j-1]) % 1000000

