            build_tree_core(inorder, inorder_index_map, postor_idx_map[postor[postor_idx]], postor, postor_idx_map, postor_end, result)

    inorder_index_map = {k: i for i, k in enumerate(inorder)}
    postor_idx_map = {k: i for i, k in enumerate(postorder)}

    result = []

    build_tree_core(inorder, inorder_index_map, 0, postorder, postor_idx_map, len(postorder) - 1, result)

