def next_permutation(perm: list) -> bool:
    # Find the index of the element that can be swapped to create a larger permutation
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    else:
        # If no such element is found, the current permutation is the last permutation
        return False

    # Find the index of the smallest element greater than perm[i]
    smallest_index = i + 1

    for j in range(i + 2, len(perm)):
        if perm[j] > perm[i] and perm[j] < perm[smallest_index]:
            smallest_index = j

    # Swap perm[i] and perm[smallest_index]
    perm[i], perm[smallest_index] = perm[smallest_index], perm[i]

    # Reverse the suffix starting from perm[i+1]
    perm[i + 1:] = perm[i + 1:][::-1]

    return True
